// Achata o payload da Cloud API em itens: mensagens e status.
// 017: origem do anúncio (referral do Click-to-WhatsApp) e tipos não suportados viram texto.
const MIDIA = ['image', 'audio', 'video', 'document', 'sticker', 'voice'];
const out = [];
for (const entry of ($json.body?.entry ?? [])) {
  for (const change of (entry.changes ?? [])) {
    const v = change.value ?? {};
    const phone_number_id = v.metadata?.phone_number_id;
    const names = Object.fromEntries((v.contacts ?? []).map(c => [c.wa_id, c.profile?.name]));
    for (const m of (v.messages ?? [])) {
      let body = null, media = null, nao_suportada = null;
      if (m.type === 'text') body = m.text?.body;
      else if (m.type === 'button') body = m.button?.text;
      else if (m.type === 'interactive') body = m.interactive?.button_reply?.title ?? m.interactive?.list_reply?.title;
      else if (MIDIA.includes(m.type)) {
        const part = m[m.type] ?? {};
        media = { type: m.type, id: part.id, mime_type: part.mime_type, caption: part.caption ?? null, filename: part.filename ?? null };
        body = part.caption ?? null;
      }
      else if (m.type === 'location') body = `[Localização: ${m.location?.name ?? ''} ${m.location?.address ?? ''} (${m.location?.latitude}, ${m.location?.longitude})]`.replace(/\s+/g, ' ');
      else if (m.type === 'contacts') body = '[Contato compartilhado: ' + (m.contacts ?? []).map(c => c.name?.formatted_name ?? '').join(', ') + ']';
      else if (m.type === 'reaction') continue;                      // reação a mensagem: não vira linha
      else {
        nao_suportada = m.type === 'unsupported' ? (m.errors?.[0]?.error_data?.details ?? m.errors?.[0]?.title ?? 'unsupported') : (m.type ?? 'desconhecido');
        body = `[Mensagem não suportada pelo WhatsApp: ${m.type ?? 'desconhecido'}]`;
      }
      const r = m.referral;
      const referral = r ? { source_id: r.source_id ?? null, source_type: r.source_type ?? null, headline: r.headline ?? null, body: r.body ?? null,
                             ctwa_clid: r.ctwa_clid ?? null, source_url: r.source_url ?? null, media_type: r.media_type ?? null } : null;
      out.push({ json: { kind: 'message', phone_number_id, wa_id: m.from, name: names[m.from] ?? null, wa_message_id: m.id, body, media, referral, nao_suportada, ts: Number(m.timestamp) } });
    }
    for (const s of (v.statuses ?? [])) {
      out.push({ json: { kind: 'status', phone_number_id, wa_message_id: s.id, status: s.status, error: s.errors?.[0]?.title ?? null } });
    }
  }
}
return out;

