select
  l.id as lead_id, l.office_id, l.phase, c.id as conversation_id, ct.wa_id, wn.phone_number_id, wn.token_secret_name,
  public.agent_config_full_lead(l.id) as agent,
  public.conversation_context(c.id, 30) as context,
  public.lead_dossier(l.id) as dossier,
  public.agent_tags_context(l.id) as etiquetas
from public.conversations c
join public.leads l on l.id = c.lead_id
join public.contacts ct on ct.id = c.contact_id
join public.whatsapp_numbers wn on wn.id = c.whatsapp_number_id
where c.id = $1;

