// Monta o caminho no bucket e, para imagem/PDF, o pedido de classificação ao Claude.
const it = $('Extrair itens').item.json;
const ing = $('ingest_inbound (linha primeiro)').item.json.r;
const bin = $input.item.binary?.arquivo;
if (!bin) return [{ json: { ok: false, motivo: 'download falhou' } }];
const mime = it.media?.mime_type || bin.mimeType || 'application/octet-stream';
const extMap = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'application/pdf': 'pdf', 'video/mp4': 'mp4', 'video/3gpp': '3gp',
                 'application/msword': 'doc', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx' };
const ext = extMap[mime] || (it.media?.filename?.split('.').pop() ?? 'bin').toLowerCase();
const path = `${ing.office_id}/${ing.lead_id}/${ing.message_id}.${ext}`;
const buf = await this.helpers.getBinaryDataBuffer(0, 'arquivo');
const classificar = mime.startsWith('image/') || mime === 'application/pdf';
const tipos = 'rg, cnh, cpf, ctps, holerite, comprovante_pix, extrato_fgts, trct, atestado, laudo, print_conversa, foto, outro';
const bloco = mime === 'application/pdf'
  ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: buf.toString('base64') } }
  : { type: 'image', source: { type: 'base64', media_type: mime, data: buf.toString('base64') } };
const request = classificar ? {
  model: 'claude-sonnet-5', max_tokens: 50, thinking: { type: 'disabled' },
  messages: [{ role: 'user', content: [bloco, { type: 'text', text:
    `Classifique este documento enviado por um trabalhador ao escritório de advocacia. Responda SOMENTE com uma destas palavras: ${tipos}. Use "foto" para foto comum (local de trabalho, lesão, uniforme) e "print_conversa" para captura de tela de conversa.` +
    (it.media?.caption ? ` Legenda enviada: "${it.media.caption}".` : '') }] }]
} : null;
return [{ json: { ok: true, path, mime, ext, size: buf.length, classificar, request, message_id: ing.message_id,
                  filename: it.media?.filename ?? null, caption: it.media?.caption ?? null },
          binary: { arquivo: bin } }];

// Tipo final do documento; sem classificação (vídeo, docx) ou com erro, cai no padrão pelo tipo de arquivo.
const prep = $('Preparar arquivo e classificação').item;
const tipos = ['rg','cnh','cpf','ctps','holerite','comprovante_pix','extrato_fgts','trct','atestado','laudo','print_conversa','foto','outro'];
const txt = String($json.content?.[0]?.text ?? '').toLowerCase().trim().replace(/[^a-z_]/g, '');
const padrao = prep.json.mime.startsWith('image/') ? 'foto' : 'outro';
const doc_tipo = tipos.includes(txt) ? txt : padrao;
return [{ json: { ...prep.json, doc_tipo }, binary: prep.binary }];

// Datacrazy: normalizador pendente. Precisa do formato oficial do webhook de mensagem recebida (ver README, P3).
// Quando existir, este nó devolve os mesmos itens do 'Extrair itens' (kind, phone_number_id/identificador do canal, wa_id, name, wa_message_id, body, media, ts)
// e o resto do fluxo (ingest_inbound, agente, efeitos) não muda.
return [];
